import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"GhostBrain — Gemini to API","description":"Turn a free Gemini web account into a real OpenAI + Anthropic-compatible API: secure session binding, multi-account pools, SSE streaming.","frontmatter":{"title":"GhostBrain — Gemini to API","description":"Turn a free Gemini web account into a real OpenAI + Anthropic-compatible API: secure session binding, multi-account pools, SSE streaming."},"headers":[],"relativePath":"en/projects/ghost-brain/index.md","filePath":"en/projects/ghost-brain/index.md"}`),a={name:`en/projects/ghost-brain/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="ghostbrain-—-gemini-to-api" tabindex="-1">GhostBrain — Gemini to API <a class="header-anchor" href="#ghostbrain-—-gemini-to-api" aria-label="Permalink to “GhostBrain — Gemini to API”">​</a></h1><p><strong><a href="https://github.com/Godde3s/GhostBrain" target="_blank" rel="noreferrer">GhostBrain</a></strong> resurrects a free Gemini web account as real infrastructure. The web app gives you a powerful model behind a chat page; GhostBrain lifts it out and serves it as a proper API — with the polish that implies: secure session binding, multi-account pools, SSE streaming and persistence.</p><h2 id="design-decisions" tabindex="-1">Design decisions <a class="header-anchor" href="#design-decisions" aria-label="Permalink to “Design decisions”">​</a></h2><p>The fragile part of any web-account bridge is the session. GhostBrain treats it as a first-class citizen: cookies are stored encrypted, sessions are health-checked and rotated before they die instead of after, and accounts are pooled so no single identity absorbs all the traffic. When a session does die, the pool quietly marks it and keeps serving — your client never sees a 401.</p><table tabindex="0"><thead><tr><th>Concern</th><th>Approach</th></tr></thead><tbody><tr><td>Session security</td><td>Encrypted cookie vault, no plaintext secrets on disk.</td></tr><tr><td>Reliability</td><td>Background health probes + automatic rotation.</td></tr><tr><td>Compatibility</td><td>OpenAI <code>/v1/chat/completions</code> and Anthropic <code>/v1/messages</code>.</td></tr><tr><td>Streaming</td><td>Native SSE relay, token-for-token.</td></tr><tr><td>Language</td><td>Python — async I/O end to end.</td></tr></tbody></table><h2 id="where-it-fits-my-stack" tabindex="-1">Where it fits my stack <a class="header-anchor" href="#where-it-fits-my-stack" aria-label="Permalink to “Where it fits my stack”">​</a></h2><p>GhostBrain is the Python sibling of <a href="/Usf/en/projects/glm-free-api/">GLM Free API</a>, and both are upstreams my <a href="/Usf/en/projects/omnirouter/">OmniRouter</a> happily load-balances. Deployed together on free tiers — Hugging Face Spaces, Railway, Render — they give me a multi-model API fleet whose monthly bill is exactly zero. That combination is what my <a href="/Usf/en/projects/hermes-stack/">Hermes Stack</a> ships as a one-click package.</p><div class="tip custom-block"><p class="custom-block-title">Responsible use</p><p>Free-tier bridges live on someone else&#39;s generosity. GhostBrain rate-limits itself and rotates accounts precisely so it stays polite — use it like a guest, not a looter.</p></div>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};